const aiOutput = $json.output || 'Вибачте, сталася помилка 🙏';
const pd = $('Prepare Context').first().json;

let text = aiOutput;
let qr = [];

const bm = text.match(/\[BUTTONS:\s*(.+?)\]/);
if (bm) {
  text = text.replace(/\[BUTTONS:\s*.+?\]/, '').trim();
  qr = bm[1].split('|').map(b => b.trim()).filter(b => b).slice(0, 13)
    .map(l => ({ content_type: 'text', title: l.substring(0, 20), payload: l.substring(0, 20) }));
}
if (text.length > 950) text = text.substring(0, 947) + '...';

const msg = { text };
if (qr.length) msg.quick_replies = qr;

return [{ json: { senderId: pd.senderId, messagePayload: msg, accessToken: pd.accessToken } }];
